// 1. Validate Input Sample
if (mh_input.sample == NULL || !adcs_is_finite_vec3(mh_input.sample)) {
    mh_state.mode = MH_FAULT;
    mh_output.mode = MH_FAULT;
    return;
}

// 2. Validate Configuration
if (mh_config.required < 4 || mh_config.required > 100) {
    mh_state.mode = MH_FAULT;
    mh_output.mode = MH_FAULT;
    return;
}
if (!isfinite(mh_config.minimum_span) || mh_config.minimum_span <= 0.0) {
    mh_state.mode = MH_FAULT;
    mh_output.mode = MH_FAULT;
    return;
}
if (!isfinite((double)mh_config.max_rejected_windows) || 
    mh_config.max_rejected_windows > 1000) {
    mh_state.mode = MH_FAULT;
    mh_output.mode = MH_FAULT;
    return;
}

// 3. Handle Disable
if (!mh_input.enable) {
    mh_state.mode = MH_IDLE;
    mh_state.count = 0;
    mh_state.rejected = 0;
    mh_state.minimum.x = 0.0; mh_state.minimum.y = 0.0; mh_state.minimum.z = 0.0;
    mh_state.maximum.x = 0.0; mh_state.maximum.y = 0.0; mh_state.maximum.z = 0.0;

    mh_output.mode = MH_IDLE;
    mh_output.count = 0;
    mh_output.rejected = 0;
    mh_output.bias.x = 0.0; mh_output.bias.y = 0.0; mh_output.bias.z = 0.0;
    mh_output.half_span.x = 0.0; mh_output.half_span.y = 0.0; mh_output.half_span.z = 0.0;
    mh_output.span_norm = 0.0;
    mh_output.span_energy = 0.0;
    return;
}

// 4. If currently in Fault, maintain Fault status
if (mh_state.mode == MH_FAULT) {
    mh_output.mode = MH_FAULT;
    return;
}

adcs_vec3_t sample = *mh_input.sample;

// 5. State Machine Execution
if (mh_state.mode == MH_IDLE) {
    mh_state.minimum = sample;
    mh_state.maximum = sample;
    mh_state.count = 1;
    mh_state.mode = MH_COLLECT;
} 
else if (mh_state.mode == MH_COLLECT) {
    // Update Extrema
    if (sample.x < mh_state.minimum.x) mh_state.minimum.x = sample.x;
    if (sample.y < mh_state.minimum.y) mh_state.minimum.y = sample.y;
    if (sample.z < mh_state.minimum.z) mh_state.minimum.z = sample.z;

    if (sample.x > mh_state.maximum.x) mh_state.maximum.x = sample.x;
    if (sample.y > mh_state.maximum.y) mh_state.maximum.y = sample.y;
    if (sample.z > mh_state.maximum.z) mh_state.maximum.z = sample.z;

    mh_state.count++;

    if (mh_state.count >= mh_config.required) {
        // Window Complete: Calculate Bias and Half-Span
        adcs_vec3_t bias;
        adcs_vec3_t half_span;

        bias.x = (mh_state.minimum.x + mh_state.maximum.x) * 0.5;
        bias.y = (mh_state.minimum.y + mh_state.maximum.y) * 0.5;
        bias.z = (mh_state.minimum.z + mh_state.maximum.z) * 0.5;

        half_span.x = (mh_state.maximum.x - mh_state.minimum.x) * 0.5;
        half_span.y = (mh_state.maximum.y - mh_state.minimum.y) * 0.5;
        half_span.z = (mh_state.maximum.z - mh_state.minimum.z) * 0.5;

        // Check Sufficient Excitation
        int sufficient = 1;
        if (half_span.x < mh_config.minimum_span) sufficient = 0;
        if (half_span.y < mh_config.minimum_span) sufficient = 0;
        if (half_span.z < mh_config.minimum_span) sufficient = 0;

        if (sufficient) {
            // Calibration Successful
            mh_state.mode = MH_READY;
            mh_state.bias = bias;

            mh_output.mode = MH_READY;
            mh_output.bias = bias;
            mh_output.half_span = half_span;
            mh_output.span_norm = adcs_vec3_norm(&half_span);
            mh_output.span_energy = adcs_vec3_dot(&half_span, &half_span);

            // Start next window
            mh_state.count = 0;
        } else {
            // Insufficient Excitation
            unint32 max_rej = mh_config.max_rejected_windows;

            if (max_rej == 0) {
                // Unlimited rejection tolerance: restart immediately
                mh_state.count = 0;
            } else {
                // Limited tolerance
                mh_state.rejected++;
                if (mh_state.rejected > max_rej) {
                    mh_state.mode = MH_FAULT;
                    mh_output.mode = MH_FAULT;
                } else {
                    // Restart collection
                    mh_state.count = 0;
                }
            }

            // Update output for non-ready state
            mh_output.mode = mh_state.mode;
            mh_output.count = mh_state.count;
            mh_output.rejected = mh_state.rejected;
            // Bias/HalfSpan remain from previous successful calibration or initial 0
            // They are not updated with insufficient data per strict interpretation
        }
    }
} 
else if (mh_state.mode == MH_READY) {
    // While Ready, treat new sample as start of new window
    mh_state.minimum = sample;
    mh_state.maximum = sample;
    mh_state.count = 1;
    mh_state.mode = MH_COLLECT;

    // Output remains from previous successful calibration
}

// 6. Populate Output for Active States (IDLE, COLLECT)
if (mh_state.mode == MH_IDLE || mh_state.mode == MH_COLLECT) {
    mh_output.mode = mh_state.mode;
    mh_output.count = mh_state.count;
    mh_output.rejected = mh_state.rejected;

    // Estimate current bias/half_span from collected data
    mh_output.bias.x = (mh_state.minimum.x + mh_state.maximum.x) * 0.5;
    mh_output.bias.y = (mh_state.minimum.y + mh_state.maximum.y) * 0.5;
    mh_output.bias.z = (mh_state.minimum.z + mh_state.maximum.z) * 0.5;

    mh_output.half_span.x = (mh_state.maximum.x - mh_state.minimum.x) * 0.5;
    mh_output.half_span.y = (mh_state.maximum.y - mh_state.minimum.y) * 0.5;
    mh_output.half_span.z = (mh_state.maximum.z - mh_state.minimum.z) * 0.5;

    // span_norm and span_energy are only valid for completed windows (READY)
    // They retain their value from the last READY state or 0 if never READY
}

