if (mh_input.sample == NULL || !adcs_is_finite_vec3(mh_input.sample)) {
    mh_state.mode = MH_FAULT;
    goto output_fault;
}

const adcs_vec3_t *sample = mh_input.sample;

switch (mh_state.mode) {
    case MH_IDLE:
        mh_state.mode = MH_COLLECT;
        mh_state.count = 1;
        mh_state.minimum.x = sample->x; mh_state.minimum.y = sample->y; mh_state.minimum.z = sample->z;
        mh_state.maximum.x = sample->x; mh_state.maximum.y = sample->y; mh_state.maximum.z = sample->z;

        mh_output.mode = MH_COLLECT;
        mh_output.count = 1;
        mh_output.rejected = 0;
        mh_output.bias.x = 0.0; mh_output.bias.y = 0.0; mh_output.bias.z = 0.0;
        mh_output.half_span.x = 0.0; mh_output.half_span.y = 0.0; mh_output.half_span.z = 0.0;
        mh_output.span_norm = 0.0;
        mh_output.span_energy = 0.0;
        break;

    case MH_COLLECT:
    case MH_READY: {
        // Update extrema
        if (sample->x < mh_state.minimum.x) mh_state.minimum.x = sample->x;
        else if (sample->x > mh_state.maximum.x) mh_state.maximum.x = sample->x;

        if (sample->y < mh_state.minimum.y) mh_state.minimum.y = sample->y;
        else if (sample->y > mh_state.maximum.y) mh_state.maximum.y = sample->y;

        if (sample->z < mh_state.minimum.z) mh_state.minimum.z = sample->z;
        else if (sample->z > mh_state.maximum.z) mh_state.maximum.z = sample->z;

        mh_state.count++;

        if (mh_state.count >= mh_config.required) {
            double bias_x = (mh_state.minimum.x + mh_state.maximum.x) * 0.5;
            double bias_y = (mh_state.minimum.y + mh_state.maximum.y) * 0.5;
            double bias_z = (mh_state.minimum.z + mh_state.maximum.z) * 0.5;

            double half_span_x = (mh_state.maximum.x - mh_state.minimum.x) * 0.5;
            double half_span_y = (mh_state.maximum.y - mh_state.minimum.y) * 0.5;
            double half_span_z = (mh_state.maximum.z - mh_state.minimum.z) * 0.5;

            adcs_vec3_t bias_v = {bias_x, bias_y, bias_z};
            adcs_vec3_t half_span_v = {half_span_x, half_span_y, half_span_z};

            double span_norm = adcs_vec3_norm(&half_span_v);
            double span_energy = adcs_vec3_dot(&half_span_v, &half_span_v);

            int all_satisfied = 1;
            if (half_span_x < mh_config.minimum_span) all_satisfied = 0;
            if (half_span_y < mh_config.minimum_span) all_satisfied = 0;
            if (half_span_z < mh_config.minimum_span) all_satisfied = 0;

            if (all_satisfied) {
                mh_state.mode = MH_READY;
                mh_state.bias = bias_v;

                mh_output.mode = MH_READY;
                mh_output.count = mh_state.count;
                mh_output.rejected = mh_state.rejected;
                mh_output.bias = bias_v;
                mh_output.half_span = half_span_v;
                mh_output.span_norm = span_norm;
                mh_output.span_energy = span_energy;
            } else {
                mh_state.rejected++;

                if (mh_config.max_rejected_windows != 0 && 
                    mh_state.rejected > mh_config.max_rejected_windows) {
                    mh_state.mode = MH_FAULT;
