            // Check sufficiency for each component
            if (hx >= mh_config.minimum_span && 
                hy >= mh_config.minimum_span && 
                hz >= mh_config.minimum_span) {
                // Success: Transition to READY
                mh_state.bias.x = (mh_state.minimum.x + mh_state.maximum.x) * 0.5;
                mh_state.bias.y = (mh_state.minimum.y + mh_state.maximum.y) * 0.5;
                mh_state.bias.z = (mh_state.minimum.z + mh_state.maximum.z) * 0.5;
                mh_state.mode = MH_READY;
            } else {
                // Insufficient excitation
                mh_state.rejected++;
                if (mh_config.max_rejected_windows > 0 && 
                    mh_state.rejected >= mh_config.max_rejected_windows) {
                    mh_state.mode = MH_FAULT;
                } else {
                    // Restart collection
                    mh_state.count = 0;
                    mh_state.minimum.x = 0.0; mh_state.minimum.y = 0.0; mh_state.minimum.z = 0.0;
                    mh_state.maximum.x = 0.0; mh_state.maximum.y = 0.0; mh_state.maximum.z = 0.0;
                }
            }
        }
    }
    // MH_READY and MH_FAULT modes do not update internal state or count

    // 5. Prepare Output
    // Half-span is derived from min/max stored in state
    adcs_vec3_t out_half_span;
    out_half_span.x = (mh_state.maximum.x - mh_state.minimum.x) * 0.5;
    out_half_span.y = (mh_state.maximum.y - mh_state.minimum.y) * 0.5;
    out_half_span.z = (mh_state.maximum.z - mh_state.minimum.z) * 0.5;

    double span_norm = sqrt(out_half_span.x * out_half_span.x + 
                            out_half_span.y * out_half_span.y + 
                            out_half_span.z * out_half_span.z);
    double span_energy = out_half_span.x * out_half_span.x + 
                         out_half_span.y * out_half_span.y + 
                         out_half_span.z * out_half_span.z;

publish_output:
    mh_output.mode = mh_state.mode;
    mh_output.count = mh_state.count;
    mh_output.rejected = mh_state.rejected;
    mh_output.bias = mh_state.bias;
    mh_output.half_span = out_half_span;
    mh_output.span_norm = span_norm;
    mh_output.span_energy = span_energy;

candidates.misra:
// 1. Validate configuration and inputs
int valid_config = 1;
if (mh_input.sample == NULL || 
    !isfinite(mh_config.minimum_span) || 
    mh_config.minimum_span <= 0.0 || 
    mh_config.required < 4 || mh_config.required > 100 || 
    mh_config.max_rejected_windows > 1000) {
    mh_state.mode = MH_FAULT;
    valid_config = 0;
}

// 2. Handle Disable
if (!mh_input.enable) {
    mh_state.mode = MH_IDLE;
    mh_state.count = 0;
    mh_state.rejected = 0;
    mh_state.minimum.x = 0.0; mh_state.minimum.y = 0.0; mh_state.minimum.z = 0.0;
    mh_state.maximum.x = 0.0; mh_state.maximum.y = 0.0; mh_state.maximum.z = 0.0;
    valid_config = 0;
} else if (valid_config) {
    // 3. Validate Sample
    if (!adcs_is_finite_vec3(mh_input.sample)) {
        mh_state.mode = MH_FAULT;
        valid_config = 0;
    } else {
        // 4. State Machine Processing
        if (mh_state.mode == MH_COLLECT) {
            // Update Min/Max
            mh_state.minimum.x = (mh_state.count == 0) ? mh_input.sample->x : fmin(mh_state.minimum.x, mh_input.sample->x);
            mh_state.minimum.y = (mh_state.count == 0) ? mh_input.sample->y : fmin(mh_state.minimum.y, mh_input.sample->y);
            mh_state.minimum.z = (mh_state.count == 0) ? mh_input.sample->z : fmin(mh_state.minimum.z, mh_input.sample->z);

            mh_state.maximum.x = (mh_state.count == 0) ? mh_input.sample->x : fmax(mh_state.maximum.x, mh_input.sample->x);
            mh_state.maximum.y = (mh_state.count == 0) ? mh_input.sample->y : fmax(mh_state.maximum.y, mh_input.sample->y);
            mh_state.maximum.z = (mh_state.count == 0) ? mh_input.sample->z : fmax(mh_state.maximum.z, mh_input.sample->z);

            mh_state.count++;

            if (mh_state.count == mh_config.required) {
                // Calculate Bias and Half-Span components
                double hx = (mh_state.maximum.x - mh_state.minimum.x) * 0.5;
                double hy = (mh_state.maximum.y - mh_state.minimum.y) * 0.5;
                double hz = (mh_state.maximum.z - mh_state.minimum.z) * 0.5;

                // Check sufficiency for each component
                if (hx >= mh_config.minimum_span && 
                    hy >= mh_config.minimum_span && 
                    hz >= mh_config.minimum_span) {
                    // Success: Transition to READY
                    mh_state.bias.x = (mh_state.minimum.x + mh_state.maximum.x) * 0.5;
                    mh_state.bias.y = (mh_state.minimum.y + mh_state.maximum.y) * 0.5;
                    mh_state.bias.z = (mh_state.minimum.z + mh_state.maximum.z) * 0.5;
                    mh_state.mode = MH_READY;
                } else {
                    // Insufficient excitation
                    mh_state.rejected++;
                    if (mh_config.max_rejected_windows > 0 && 
                        mh_state.rejected >= mh_config.max_rejected_windows) {
                        mh_state.mode = MH_FAULT;
                    } else {
                        // Restart collection
                        mh_state.count = 0;
                        mh_state.minimum.x = 0.0; mh_state.minimum.y = 0.0; mh_state.minimum.z = 0.0;
                        mh_state.maximum.x = 0.0; mh_state.maximum.y = 0.0; mh_state.maximum.z = 0.0;
                    }
                }
            }
        }
        // MH_READY and MH_FAULT modes do not update internal state or count
    }
}

// 5. Prepare Output
adcs_vec3_t out_half_span;
if (mh_state.mode == MH_IDLE) {
    out_half_span.x = 0.0;
    out_half_span.y = 0.0;
    out_half_span.z = 0.0;
} else {
    out_half_span.x = (mh_state.maximum.x - mh_state.minimum.x) * 0.5;
    out_half_span.y = (mh_state.maximum.y - mh_state.minimum.y) * 0.5;
    out_half_span.z = (mh_state.maximum.z - mh_state.minimum.z) * 0.5;
}

double span_norm = sqrt(out_half_span.x * out_half_span.x + 
                        out_half_span.y * out_half_span.y + 
                        out_half_span.z * out_half_span.z);
double span_energy = out_half_span.x * out_half_span.x + 
                     out_half_span.y * out_half_span.y + 
                     out_half_span.z * out_half_span.z;

mh_output.mode = mh_state.mode;
mh_output.count = mh_state.count;
mh_output.rejected = mh_state.rejected;
mh_output.bias = mh_state.bias;
mh_output.half_span = out_half_span;
mh_output.span_norm = span_norm;
mh_output.span_energy = span_energy;
